        x, y = 0, 0
        visited = set()
        visited.add((x, y))

        for direction, distance in commands:
            if direction == "up":
                dx, dy = -1, 0
            elif direction == "down":
                dx, dy = 1, 0
            elif direction == "left":
                dx, dy = 0, -1
            elif direction == "right":
                dx, dy = 0, 1

            for _ in range(distance):
                x += dx
                y += dy
                if (x, y) in visited:
                    continue
                visited.add((x, y))
                if len(visited) > t:
                    return False
                if board[x][y] == '#':
                    return False
        return True

    # Binary search for the minimum time
    left, right = 0, h * w
    min_time = -1
    while left <= right:
        mid = (left + right) // 2
        if can_draw_at_time(mid):
            min_time = mid
            right = mid - 1
        else:
            left = mid + 1

    # If it's impossible to draw the target drawing
    if min_time == -1:
        return -1, -1

    # Binary search for the maximum time
    left, right = min_time, h * w
    max_time = -1
    while left <= right:
        mid = (left + right) // 2
        if can_draw_at_time(mid):
            max_time = mid
            left = mid + 1
        else:
            right = mid - 1

    return min_time, max_time

