                    continue
                visited.add((x, y))
                if t > 0:
                    t -= 1
                else:
                    return False
        return all((x, y) in visited and board[x][y] == '#' for x, y in visited)

    def binary_search(low, high):
        while low < high:
            mid = (low + high) // 2
            if can_draw_by_time(mid):
                high = mid
            else:
                low = mid + 1
        return low

    if not can_draw_by_time(h * w):
        return -1, -1

    min_time = binary_search(0, h * w)
    max_time = binary_search(min_time, h * w)

    return min_time, max_time

